===== bamboo-spec-conditional-build-triggers.yml =====
# yaml-language-server: $schema=../../schemas/json/bamboo-spec.json
version: 2
triggers:
  - polling:
      period: 900
      conditions:
        - all-other-conditions:
            custom.rejectBranchBuildWithoutChange.enabled: true

