{
  "Production": {
    "notifications": [
      {
        "events": "deployment-failed",
        "recipients": [
          {
            "groups": ["bamboo-admin", "bamboo-users"]
          },
          {
            "groups": ["bamboo-devs"]
          }
        ]
      }
    ],
    "tasks": [
      "clean",
      {
        "artifact-download": {
          "destination": "/workdir",
          "name": "AllPackages"
        }
      },
      {
        "script": {
          "interpreter": "cmd",
          "scripts": ["echo 'hello world'", "echo \"I'm done\""]
        }
      }
    ],
    "triggers": [
      {
        "environment-success": "Staging"
      },
      {
        "cron": "0 0 0 ? * *"
      }
    ],
    "variables": {
      "variableName": "variableValue"
    }
  },
  "QA": {
    "docker": {
      "image": "docker-image-name"
    },
    "final-tasks": [
      {
        "script": ["echo \"let's clean it up\""]
      },
      {
        "artifact-download": {
          "artifacts": [
            {
              "destination": "/my-artifacts",
              "name": "my-artifacts"
            },
            {
              "name": "their-artifacts"
            }
          ]
        }
      }
    ],
    "notifications": [
      {
        "events": ["deployment-started-and-finished"],
        "recipients": [
          {
            "users": ["admin", "joe"]
          },
          {
            "groups": ["bamboo-admin"]
          }
        ]
      },
      {
        "events": ["deployment-failed", "deployment-finished"],
        "recipients": [
          {
            "emails": ["admin@gmail.com", "joe@gmail.com"]
          }
        ]
      }
    ],
    "requirements": ["isDragonLazy"],
    "tasks": [
      "clean",
      {
        "artifact-download": {
          "destination": "/workdir"
        }
      },
      {
        "script": ["echo 'hello world'", "echo \"I'm done\""]
      },
      {
        "artifact-download": {
          "artifacts": [
            {
              "destination": "/my-artifacts",
              "name": "my-artifacts"
            }
          ]
        }
      }
    ],
    "triggers": [
      "build-success",
      {
        "stage-success": {
          "stage": "Stage 2"
        }
      },
      {
        "stage-success": {
          "branch": "develop-branch",
          "stage": "Stage 3"
        }
      }
    ],
    "variables": {
      "variableName": "variableValue"
    }
  },
  "Staging": {
    "docker": {
      "image": "docker-image-name",
      "use-default-volumes": false,
      "volumes": {
        "${bamboo.tmp.directory}": "${bamboo.tmp.directory}",
        "${bamboo.working.directory}": "${bamboo.working.directory}"
      }
    },
    "notifications": [
      {
        "events": [
          "deployment-failed",
          "deployment-finished",
          "deployment-started-and-finished"
        ],
        "recipients": [
          {
            "users": ["admin", "joe"]
          },
          {
            "groups": ["bamboo-admin", "bamboo-users"]
          },
          {
            "emails": ["admin@gmail.com", "joe@gmail.com"]
          }
        ]
      }
    ],
    "tasks": [
      "clean",
      {
        "artifact-download": {
          "destination": "/workdir"
        }
      },
      {
        "script": ["echo 'hello world'", "echo \"I'm done\""]
      },
      "artifact-download"
    ],
    "triggers": [
      {
        "stage-success": "dragons stage"
      },
      {
        "build-success": {
          "branch": "stage-ready-branch"
        }
      }
    ],
    "variables": {
      "variableName": "variableValue"
    }
  },
  "deployment": {
    "name": "Deployment project name",
    "source-plan": "PLAN-KEY"
  },
  "environments": ["QA", "Staging", "Production"],
  "release-naming": {
    "applies-to-branches": true,
    "auto-increment": true,
    "auto-increment-variables": ["quickCompileMavenGoals.experimental"],
    "next-version-name": "0.${bamboo.buildNumber}.${bamboo.quickCompileMavenGoals.experimental}"
  },
  "version": 2
}

